/*
ElementSets, BoundaryMatrices from MeshConnectivity
M ∈ FaceMesh
V, E, F = ElementSets(M)
`∂⁰`, `∂¹` = BoundaryMatrices(M)
L = `∂⁰` `∂⁰`ᵀ

*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>
#include "type_helper.h"
#include "FaceMesh.h"
#include "MeshHelper.h"

using namespace iheartmesh;
struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    std::vector<int > V;
    std::vector<int > E;
    std::vector<int > F;
    Eigen::SparseMatrix<int> dee0;
    Eigen::SparseMatrix<int> dee1;
    Eigen::SparseMatrix<int> L;
    FaceMesh M;
    heartlib(const FaceMesh & M)
    {
        // V, E, F = ElementSets(M)
        std::tuple< std::vector<int >, std::vector<int >, std::vector<int > > rhs = M.ElementSets();
        V = std::get<0>(rhs);
        E = std::get<1>(rhs);
        F = std::get<2>(rhs);
        int dimv_0 = M.n_vertices();
        int dime_0 = M.n_edges();
        int dimf_0 = M.n_faces();
        this->M = M;
        // `∂⁰`, `∂¹` = BoundaryMatrices(M)
        std::tuple< Eigen::SparseMatrix<int>, Eigen::SparseMatrix<int> > rhs_1 = M.BoundaryMatrices();
        dee0 = std::get<0>(rhs_1);
        dee1 = std::get<1>(rhs_1);
        // L = `∂⁰` `∂⁰`ᵀ
        L = dee0 * dee0.transpose();
    }
};

