%    V, E, F = ElementSets(M)
%    `∂⁰`, `∂¹` = BoundaryMatrices(M)
%    L = `∂⁰` `∂⁰`ᵀ
%    
    dimv_0 = M.n_vertices();
    dime_0 = M.n_edges();
    dimf_0 = M.n_faces();
    [V, E, F] = M.ElementSets();
    [dee0, dee1] = M.BoundaryMatrices();
    % L = `∂⁰` `∂⁰`ᵀ

    L = dee0 * dee0';
